    'zc.ushrNisabNote': 'No ushr is due on a harvest below 653 kg (five wasq).',
    'zc.disclaimer': 'This is a guide, not a fatwa. If your situation is unusual — inherited gold, a business in loss, a debt you may never recover — ask a scholar. The committee is happy to help you find one.',
    'pzk.title': 'Zakat & Ushr',
    'pzk.blurb': 'Give into the pool, and a verified register decides the split by a rule fixed before collection began.',
    'pzk.whyUrdu': 'اکثر زکوٰۃ ایک ہی نظر آنے والے حاجت مند تک بار بار پہنچتی ہے اور باقی محروم رہ جاتے ہیں۔ اسی لیے یہاں دینے والا وصول کرنے والا نہیں چنتا۔ کمیٹی گھر گھر جا کر تصدیق کرتی ہے اور رقم طے شدہ اصول پر برابر تقسیم ہوتی ہے۔',
    'pzk.whyEnglish': 'You do not choose a recipient, and that is the feature rather than a limitation — it is what stops one visible family receiving everything while others receive nothing.',
    'pzk.whoItReaches': 'Who it reaches',
    'pzk.whoItReachesHelp': 'Counts only. No household on the register is ever named to a donor.',
    'pzk.stat.households': 'Verified households',
    'pzk.stat.widows': 'Widow-headed',
    'pzk.stat.orphans': 'With orphans',
    'pzk.stat.disabled': 'With a disabled member',
    'pzk.perHousehold': 'Roughly per household',
    'pzk.formulaFixed': 'This formula was fixed before collection began, so it cannot have been shaped around the total.',
    'pzk.giveZakat': 'Give your zakat',
    'wf.title': 'Welfare — how it works',
    'wf.blurb': 'Four ways the committee helps, and exactly what happens at each step. Written for the family that needs help as much as for the person giving it.',
    'wf.privacy.title': 'Your name is never published',
    'wf.privacy.urdu': 'اگر آپ مدد کے لیے اندراج کرتے ہیں تو آپ کا نام نہ اس ویب سائٹ پر آئے گا، نہ کسی عطیہ دینے والے تک پہنچے گا، نہ کسی رپورٹ میں چھپے گا۔ کمیٹی کے صرف دو تین ذمہ دار افراد آپ کی تفصیل دیکھ سکتے ہیں۔ باقی سب کو صرف ایک کوڈ نظر آتا ہے۔',
    'wf.privacy.english': 'Registering for help is private. Two or three named verifiers can open your record; everyone else — including the accountant who hands out the money — sees only a code.',
    'wf.ifYouNeed': 'If you need help',
    'wf.ifYouGive': 'If you want to give',
    'wf.howItWorks': 'What happens, step by step',
    'wf.open': 'Open this',
    'wf.zakat.title': 'Zakat & Ushr',
    'wf.zakat.lead': 'Collected into one pool and shared out among every verified household by a rule fixed in advance.',
    'wf.zakat.forNeedy': 'Tell the committee about your situation, or let a neighbour tell them. Two members will visit your home privately. If you qualify you are added to the register and share in every distribution, without ever having to ask again.',
    'wf.zakat.forGiver': 'You do not choose who receives it, and that is deliberate. It is what stops the same visible family being helped again and again while others are never reached.',
    'wf.zakat.s1': 'A household registers, or a neighbour points the committee towards one.',
    'wf.zakat.s2': 'Two committee members visit the house and record what they find.',
    'wf.zakat.s3': 'Before collection begins, the committee publishes the sharing formula.',
    'wf.zakat.s4': 'The zakat is handed over against a receipt, and a totals-only report is published.',
    'wf.zakat.stat': 'verified households',
    'wf.kafalat.title': 'Kafalat — school children',
    'wf.kafalat.lead': 'A child’s year at school paid for, in full or in shares between several people.',
    'wf.kafalat.forNeedy': 'If a child in your house has stopped going to school because of money, tell the committee. Anyone can also nominate a neighbour’s child. Nothing about the child is ever shown publicly.',
    'wf.kafalat.forGiver': 'Take a whole year or a share of one. You see the fee, uniform, books and transport as separate lines, so you know exactly what your money buys.',
    'wf.kafalat.s1': 'A family asks, or a neighbour nominates a child.',
    'wf.kafalat.s2': 'The committee visits and the guardian signs a consent form.',
    'wf.kafalat.s3': 'The year’s cost is worked out line by line — fee, uniform, books, transport.',
    'wf.kafalat.s4': 'Sponsors take shares, and the committee pays the school and reports back each term.',
    'wf.kafalat.stat': 'children supported',
    'wf.wazifa.title': 'Taleemi Wazifa — college and university',
    'wf.wazifa.lead': 'For the student who did well and stops because the family cannot find the admission fee. Normally an interest-free loan, so the same rupees reach the next student too.',
    'wf.wazifa.forNeedy': 'Register on the portal with your own phone number and fill in the form yourself — the account has to be the student’s, so the fee updates, the reminders and the record of what is owed reach the person the money follows. You can save it and come back, and you can correct anything until the committee starts reviewing it. Print it for the house visit. Help is usually a qarz-e-hasana: an interest-free loan repaid after you start earning.',
    'wf.wazifa.forGiver': 'Applications are ranked by a written formula of marks and need, so nobody is chosen because the committee knows their family better.',
    'wf.wazifa.s1': 'The student registers on the portal with their own phone number and fills in the form.',
    'wf.wazifa.s2': 'A committee member goes through it at the house and checks what it says.',
    'wf.wazifa.s3': 'Marks and need are scored, and the committee decides in a meeting.',
    'wf.wazifa.s4': 'The committee pays the institution directly against its challan — the money never passes through the student. Where a qarz-e-hasana, it is returned in instalments once they are earning.',
    'wf.wazifa.stat': 'students supported',
    'wf.esal.title': 'Esal-e-Sawab — Sadqa-e-Jariya',
    'wf.esal.lead': 'Something the village keeps using, carrying the name of someone you have lost.',
    'wf.esal.forNeedy': 'This one is for the whole village rather than one family — a water cooler at the mosque, a solar street light, a shaded bench. If your street needs something, tell the committee and it can be offered to a donor.',
    'wf.esal.forGiver': 'Choose the object and the name for the plaque. The listed price is only an estimate: the committee sends you the shop’s actual invoice, and nothing is bought until you agree it. If the bill comes in cheaper the difference stays to your credit; if it comes in dearer the difference shows as due from you. The object is then recorded in the committee’s accounts under its own name, and the reward continues for as long as it works.',
    'wf.esal.s1': 'You choose an object and the name that goes on its plaque.',
    'wf.esal.s2': 'The committee agrees the real cost with you in writing before anything is bought.',
    'wf.esal.s3': 'It is bought, installed, and photographed with its plaque.',
    'wf.esal.s4': 'It appears on the public board, and the committee keeps it working for years.',
    'wf.esal.stat': 'lasting gifts',
    'wf.calculator.title': 'Work out your zakat',
    'wf.calculator.blurb': 'Nisab, gold, silver, cash, business stock and the harvest — all in one place, with the arithmetic shown.',
    'wf.apply.title': 'How to ask for help',
    'wf.apply.urdu': 'پورٹل میں اندراج کریں اور متعلقہ فارم بھریں، یا کمیٹی کے کسی رکن سے براہِ راست بات کریں۔ اگر آپ فارم نہیں بھر سکتے تو کوئی بھی آپ کی طرف سے بھر سکتا ہے — کمیٹی بہرحال آپ سے خود بات کرے گی۔',
    'wf.apply.english': 'Sign in and fill in the relevant form, or speak to any committee member. If you cannot fill in a form, somebody else may do it for you — the committee will speak to you directly either way.',
    'wf.apply.signIn': 'Sign in to the portal',
    'wf.apply.contact': 'Contact the committee',
    'nav.welfare': 'Welfare',
    'portal.zakat': 'Zakat & Ushr',

