    // ── Family business, documents, loan agreement, live rates ───────────
    'pwz.s.business': 'Family business or joint income',
    'pwz.businessUrdu': 'اگر گھر والے مل کر کوئی کاروبار، دکان، ٹریکٹر، مال مویشی یا زمین چلاتے ہیں تو وہ یہاں لکھیں اور بتائیں کہ آپ کے گھرانے کا ماہانہ حصہ کتنا بنتا ہے۔',
    'pwz.businessEnglish': 'Families here often run one shop, one tractor or one herd between several brothers. Asking each man his "salary" gets zero from all of them and misses the household’s real income.',
    'pwz.f.hasBusiness': 'The family runs a business, shop, land or livestock together',
    'pwz.f.businessKind': 'What is it',
    'pwz.f.businessPlaceholder': 'e.g. general store, tractor on hire, 8 buffaloes, 12 kanal land',
    'pwz.f.businessShare': 'Your household’s share per month (Rs)',
    'pwz.f.businessShareHint': 'Your family’s share of the profit, not the whole business.',
    'pwz.f.businessNote': 'Anything else about it',
    'pwz.s.documents': 'Documents',
    'pwz.documentsUrdu': 'اپنی تعلیمی اسناد، ڈی ایم سی، شناختی کارڈ، داخلہ لیٹر اور فیس چالان کی تصویریں لگائیں۔ موبائل سے کھینچی گئی صاف تصویر بھی کافی ہے۔',
    'pwz.documentsEnglish': 'Attach what you have. A clear photograph taken on a phone is enough — nothing needs to be scanned.',
