    'pwz.as.grantHelp': 'For orphans and families with no earning member. The committee decides, and it will ask you why — so write your reason in the statement above.',
    'pwz.as.loan': 'Qarz-e-hasana — I will return it once I am earning (recommended)',
    'pwz.as.loanHelp': 'Interest-free — a preliminary understanding, not the final terms. If approved, the committee will fix the exact amount and instalments on a separate agreement you\'ll sign before it starts. What you repay pays for the next student from this village.',
