    // ── Home page welfare appeals — the emotive copy ─────────────────────
    'hw.wazifa.mottoUr': 'آئیے، اس ہونہار بچے کو افسر، ڈاکٹر، انجینئر بنائیں — اس کا خواب مل کر پورا کریں',
    'hw.wazifa.motto': 'Let us make this bright child an officer, a doctor, an engineer. Let us finish their dream together.',
    'hw.wazifa.body': 'Somewhere in this village a boy or girl passed matric with good marks and then stopped — not for want of ability, but because nobody had the admission fee. Normally given as qarz-e-hasana, so the same rupees carry the next student too.',
    'hw.wazifa.how': 'Apply for yourself, your own child, or a neighbour’s child. Print the form — a committee member visits the home and goes through it with the family.',
    'hw.wazifa.cta': 'Apply or sponsor a student',
    'hw.wazifa.stat1': 'students carried this far',
    'hw.wazifa.stat2': 'have finished their degree',
    'hw.kafalat.mottoUr': 'ایک بچے کا بستہ اٹھائیے — ایک سال کی فیس، ایک عمر کا فرق',
    'hw.kafalat.motto': 'Carry one child’s schoolbag. One year of fees; a lifetime of difference.',
    'hw.kafalat.body': 'Fees, uniform, books and the fare to Chakwal — set out line by line, so you see exactly what your share buys. Take a whole year or a part of one; the pool covers a child if any sponsor falls away.',
    'hw.kafalat.how': 'Anyone may nominate a child from their own street. The committee visits quietly, and no child is ever named or photographed publicly.',
    'hw.kafalat.cta': 'Sponsor a child',
    'hw.kafalat.stat1': 'children in school',
    'hw.kafalat.stat2': 'still waiting for a sponsor',
    'hw.zakat.mottoUr': 'آپ کی زکوٰۃ ایک دروازے پر نہیں، ہر مستحق گھر تک',
    'hw.zakat.motto': 'Your zakat reaches every deserving door — not the same one twice.',
    'hw.zakat.body': 'Zakat usually reaches the one family everybody can see, again and again, while others are never reached at all. Here nobody chooses a recipient: the committee visits and verifies, and a rule fixed before collection divides it.',
    'hw.zakat.how': 'Register for help yourself, or let a neighbour tell the committee. Two members visit privately, and your name never appears on this website.',
    'hw.zakat.cta': 'Work out your zakat, or give',
    'hw.zakat.stat1': 'households verified door to door',
    'hw.zakat.stat2': 'of them headed by a widow',
    'hw.esal.mottoUr': 'جب تک پانی بہتا رہے، ثواب پہنچتا رہے — اپنے پیارے کے نام پر',
    'hw.esal.motto': 'While the water still runs, the reward still reaches them.',
    'hw.esal.body': 'A water cooler at the mosque. A solar street light on a dark lane. A hand pump the whole street uses — carrying the name of a father, a mother, a brother, for as long as it keeps working.',
    'hw.esal.how': 'Choose the object and the name for the plaque. Nothing is charged until the committee has seen the spot and agreed the real cost with you.',
    'hw.esal.cta': 'See the board, or give one',
    'hw.esal.stat1': 'still working today',
    'hw.esal.stat2': 'given in all',
    'hw.privacyUr': 'اگر آپ مدد کے لیے اندراج کریں تو آپ کا نام نہ اس ویب سائٹ پر آئے گا، نہ کسی عطیہ دینے والے تک پہنچے گا۔ کمیٹی کے صرف دو تین ذمہ دار افراد آپ کی تفصیل دیکھ سکتے ہیں۔',

    // Card names — short enough to hold one line at card width.
    'hw.zakat.tab': 'Zakat & Ushr',
    'hw.kafalat.tab': 'Kafalat — School',
    'hw.wazifa.tab': 'Taleemi Wazifa',
    'hw.esal.tab': 'Esal-e-Sawab',

    // Mushtarka Kafalat — pooled monthly giving (migration 222)
    'portal.support': 'Mushtarka Giving',
    'nav.pools': 'Mushtarka Kafalat',
    'pool.title': 'Mushtarka Giving — carrying it together',
    'pool.mottoUr': 'اکیلے یہ بوجھ بھاری ہے، مل کر یہ کچھ بھی نہیں',
    'pool.intro': 'Instead of one person carrying the whole cost, many of us each give a small amount every month and together we cover every student and every shared cost the committee carries. Sponsoring a specific child has its own page — this is for joining a shared pool with no name attached.',
    'pool.bannerNeeds': 'needs {n} more people at {amt} a month',
    'pool.howTitle': 'How this works — please read before you join',
    'pool.how.what.q': 'What am I agreeing to?',
    'pool.how.what.aUr': 'آپ ہر ماہ ایک مقررہ رقم دینے کا ارادہ ظاہر کرتے ہیں۔ یہ کوئی قانونی معاہدہ نہیں۔',
    'pool.how.what.a': 'You are stating an intention to give a fixed amount each month. It is not a legal contract and nothing is ever taken from your account automatically — you send it yourself, the way you send any donation.',
    'pool.how.amount.q': 'Can my amount be increased later?',
    'pool.how.amount.aUr': 'کبھی نہیں۔ آپ کی رقم صرف آپ خود بدل سکتے ہیں۔',
    'pool.how.amount.a': 'Never without you. If somebody else stops giving, we ask new people to join — we do not quietly raise what you already agreed to. Only you can change your amount, on this page.',
    'pool.how.when.q': 'When do I pay?',
    'pool.how.when.aUr': 'ہر مہینے، جس تاریخ کو آپ کے لیے آسان ہو۔',
    'pool.how.when.a': 'Any time within the month, by cash, bank transfer, JazzCash or EasyPaisa. The accountant records it against your name and it appears in your giving statement.',
    'pool.how.stop.q': 'What if I need to stop?',
    'pool.how.stop.aUr': 'ایک کلک سے، بغیر کسی وضاحت کے۔',
    'pool.how.stop.a': 'Stop any time from this page, with no explanation asked for. If a month goes by without a payment we simply mark your share as paused — nobody will chase you, and you can start again whenever you want.',
    'pool.how.short.q': 'What if not enough people join?',
    'pool.how.short.aUr': 'کمیٹی اپنے فنڈ سے وہ مہینہ پورا کرتی ہے تاکہ کسی بچے کی تعلیم نہ رکے۔',
    'pool.how.short.a': 'The committee covers that month from its own general funds so that no child is stopped mid-year. That is a one-off for the month it happens and cannot be repeated indefinitely, which is why the appeal keeps running until enough people have joined.',
    'pool.how.privacy.q': 'Will people know what I give?',
    'pool.how.privacy.aUr': 'نہیں۔ صرف آپ اور اکاؤنٹنٹ کو معلوم ہوگا۔',
    'pool.how.privacy.a': 'No. Only you and the donor accountant can see your amount. Nobody else in the village sees who gives what, and you can give anonymously if you prefer.',
    'pool.promiseUr': 'آپ کی طے شدہ رقم آپ کی اجازت کے بغیر کبھی نہیں بڑھائی جائے گی۔',
    'pool.promise': 'Your agreed amount is never changed without you. What changes is the share we suggest to the next person who joins.',
    'pool.needsPerMonth': '{amt} needed every month',
